/// <summary>
/// PaffH 02.10.20
/// </summary>
[Form]
public class NDXSetupPlaningOfRessources extends FormRun
{
    ImageListAppl_Prod          imageList;
    ProdId lastProdId;
    int lastCountProdRec;
    const int timeOut = 60000;
    NDXSetupPlaningOfRessourcesFormHandler nDXSetupPlaningOfRessourcesFormHandler;

}

/// <summary>
/// PaffH 05.10.20
/// </summary>
public void init()
{
    super();
    nDXSetupPlaningOfRessourcesFormHandler = NDXSetupPlaningOfRessourcesFormHandler::construct(element);
    nDXSetupPlaningOfRessourcesFormHandler.ctrlListBoxInfo(ListBoxInfo);
}

/// <summary>
/// PaffH 05.10.20
/// timeout method (every 60 sec)
/// </summary>
/// <param name = "_result"></param>
[SuppressBPWarning('BPParameterNotUsed', '_result')]
private void timeOutMethod(AsyncTaskResult _result)
{
    //str infoTxt;
    if (!element.closed())
    {
        nDXSetupPlaningOfRessourcesFormHandler.fillListInfo();
        element.setTimeoutEx(formMethodStr(NDXSetupPlaningOfRessources, timeOutMethod), conNull(), timeOut);
    }
}

/// <summary>
/// PaffH 05.10.20
/// </summary>
public void run()
{
    super();
    nDXSetupPlaningOfRessourcesFormHandler.postRun();
    element.setTimeoutEx(formMethodStr(NDXSetupPlaningOfRessources, timeOutMethod), conNull(), 10);
    element.viewOptionHelper().setViewOption(FormViewOption::Details);
}

/// <summary>
/// PaffH 02.10.20
/// filter: Released, StartedUp
/// sort: ProdPrio, PordId
/// </summary>
public void init()
{
    QueryBuildDataSource qbds;
    str qValue;
    super();
    qbds = this.query().dataSourceName(this.name());
    qbds.addSortField(fieldNum(ProdTable, ProdPrio), SortOrder::Descending);
    qbds.addSortField(fieldNum(ProdTable, ProdId), SortOrder::Descending);

    qValue = strFmt("@NDX:NDXQValue01",
            fieldId2Name(tableNum(ProdTable), fieldNum(ProdTable, ProdStatus)),
            queryValue(enum2int(ProdStatus::Released)),
            queryValue(enum2int(ProdStatus::StartedUp)));
    qbds.addRange(fieldNum(ProdTable, RecId)).value(qValue);
}

